+    int numEventsPerThread = 10_000;
+    int totalEvents = numThreads * numEventsPerThread;
+    AtomicInteger idIndex = new AtomicInteger();
+    ThreadPoolExecutor pool =
+        new ThreadPoolExecutor(
+            numThreads,
+            numThreads,
+            /* keepAliveTime= */ 0,
+            TimeUnit.SECONDS,
+            /* workQueue= */ new LinkedBlockingQueue<>());
+
